{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "The 1% Chance of Survival",
      "goal": "Survive the initial transition by exploiting a 100% crit-rate bug on a tutorial boss.",
      "chapter_role": "hook",
      "stakes_shift": "From certain death to possessing an unintended mechanical advantage.",
      "bridge": {
        "from_prev": "Protagonist dies in the real world due to a freak statistical anomaly.",
        "to_next": "The protagonist enters the first hub city with a bag full of 'impossible' tutorial loot."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 2,
      "title": "Looting the Narrative",
      "goal": "Identify the 'Speed-to-Crit' conversion exploit while navigating the starter city's bureaucracy.",
      "chapter_role": "setup",
      "stakes_shift": "From lucky survivor to deliberate exploiter of system physics.",
      "bridge": {
        "from_prev": "Arriving at the hub with high-tier loot and suspicious stats.",
        "to_next": "The protagonist joins a low-stakes dungeon crawl to test his 'Hit & Run' theory."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "steady",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 3,
      "title": "The Glass Cannon Special",
      "goal": "Clear the Sunken Crypt dungeon using a zero-hit strategy that breaks the local leaderboard.",
      "chapter_role": "trial",
      "stakes_shift": "From an unknown player to a target of interest for the 'System Integrity' guild.",
      "bridge": {
        "from_prev": "Entering the dungeon with a build that shouldn't work.",
        "to_next": "The local authorities realize the protagonist is bypassing standard combat cooldowns."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 4,
      "title": "Grand Theft Artifact",
      "goal": "Infiltrate the high-security 'Admin Vault' to steal a Luck-Stabilizer before the System patches his exploit.",
      "chapter_role": "reversal",
      "stakes_shift": "From a high-performing player to a wanted 'glitch' in the world's eyes.",
      "bridge": {
        "from_prev": "The realization that a server-side update will soon nerf his crit-build.",
        "to_next": "The protagonist is forced to flee the city as a bounty is placed on his 'illegal' stats."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 5,
      "title": "Aggro Management for Dummies",
      "goal": "Evade a relentless System Corrector by manipulating mob pathing and aggro ranges in the Dead-Zone.",
      "chapter_role": "investigation",
      "stakes_shift": "From fleeing the system to learning how to rewrite its pursuit logic.",
      "bridge": {
        "from_prev": "Escaping the city with a stolen artifact and a world-wide bounty.",
        "to_next": "The protagonist discovers the source code of the Corrector's AI."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "slow_burn",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 6,
      "title": "The Zero-Percent Solution",
      "goal": "Defeat the System Corrector in a final confrontation by forcing a mathematical overflow error.",
      "chapter_role": "confrontation",
      "stakes_shift": "From being hunted by the system to becoming a permanent, unpatchable exception.",
      "bridge": {
        "from_prev": "Luring the Corrector into a zone where the physics engine is unstable.",
        "to_next": "The defeat of the Corrector causes a localized reality shift."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 7,
      "title": "Running the Numbers",
      "goal": "Establish a base of operations in the 'Glitch Zone' where the protagonist can dictate the rules.",
      "chapter_role": "aftermath",
      "stakes_shift": "From a frantic fugitive to the master of a new, exploited reality.",
      "bridge": {
        "from_prev": "Surviving the system's attempt to delete his character.",
        "to_next": "The protagonist prepares for the next 'Update' with a team of fellow outliers."
      },
      "pacing": {
        "intensity": 2,
        "tempo": "steady",
        "expected_scene_count": 6
      }
    }
  ]
}

